function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // strangers
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(100 + 50 * Math.sin(t), H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(100 + 50 * Math.sin(t), H / 2 - 20);
  ctx.lineTo(100 + 50 * Math.sin(t), H / 2 - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(100 + 50 * Math.sin(t), H / 2 + 20);
  ctx.lineTo(100 + 50 * Math.sin(t), H / 2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W - 100 + 50 * Math.cos(t), H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 100 + 50 * Math.cos(t), H / 2 - 20);
  ctx.lineTo(W - 100 + 50 * Math.cos(t), H / 2 - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 100 + 50 * Math.cos(t), H / 2 + 20);
  ctx.lineTo(W - 100 + 50 * Math.cos(t), H / 2 + 50);
  ctx.stroke();

  // community
  ctx.beginPath();
  ctx.moveTo(100 + 50 * Math.sin(t), H / 2);
  ctx.lineTo(W - 100 + 50 * Math.cos(t), H / 2);
  ctx.stroke();

  // connections
  if (Math.sin(t) > 0.5 || Math.cos(t) > 0.5) {
    ctx.beginPath();
    ctx.moveTo(100 + 50 * Math.sin(t), H / 2 - 30);
    ctx.lineTo(W - 100 + 50 * Math.cos(t), H / 2 - 30);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(100 + 50 * Math.sin(t), H / 2 + 30);
    ctx.lineTo(W - 100 + 50 * Math.cos(t), H / 2 + 30);
    ctx.stroke();
  }

  ctx.restore();
}
